#include "directinput_mouse.hpp"
#include <iostream>
template<bool W>int test(){int errors=0;auto check=[&](bool b){if(!b)++errors;};auto f=std::make_shared<hvi::MouseFeed>();auto*d=new hvi::DirectInputMouse<W>(f);void*p=nullptr;check(d->QueryInterface(W?IID_IDirectInputDevice8W:IID_IDirectInputDevice8A,&p)==S_OK);if(p)d->Release();check(d->SetDataFormat(&c_dfDIMouse2)==DI_OK);DIPROPDWORD prop{};prop.diph={sizeof(prop),sizeof(DIPROPHEADER),0,DIPH_DEVICE};prop.dwData=3;check(d->SetProperty(DIPROP_BUFFERSIZE,&prop.diph)==DI_OK);check(d->Acquire()==DI_OK);hvi::Event e;e.kind=hvi::Kind::Relative;e.a=12;e.b=-7;f->apply(e);e.kind=hvi::Kind::Button;e.a=4;e.b=1;f->apply(e);e.kind=hvi::Kind::Wheel;e.a=120;e.b=0;f->apply(e);DIMOUSESTATE2 s{};check(d->GetDeviceState(sizeof(s),&s)==DI_OK&&s.lX==12&&s.lY==-7&&s.lZ==120&&s.rgbButtons[4]==128);check(d->GetDeviceState(sizeof(s),&s)==DI_OK&&s.lX==0&&s.lZ==0);DIDEVICEOBJECTDATA data[8]{};DWORD n=8;check(d->GetDeviceData(sizeof(data[0]),data,&n,DIGDD_PEEK)==DI_BUFFEROVERFLOW&&n==3);n=8;check(d->GetDeviceData(sizeof(data[0]),data,&n,0)==DI_BUFFEROVERFLOW);n=8;check(d->GetDeviceData(sizeof(data[0]),data,&n,0)==DI_OK&&n==0);d->Unacquire();check(d->GetDeviceState(sizeof(s),&s)==DIERR_NOTACQUIRED);check(d->SetDataFormat(&c_dfDIMouse)==DI_OK);check(d->Acquire()==DI_OK);DIMOUSESTATE small{};check(d->GetDeviceState(sizeof(small),&small)==DI_OK);f->reset();check(d->GetDeviceState(sizeof(small),&small)==DI_OK&&small.rgbButtons[0]==0);check(d->Release()==0);return errors;}
int main(){int n=test<false>()+test<true>();std::cout<<"mouse errors="<<n<<"\n";return n?1:0;}